package com.multiaceites.controller; import com.multiaceites.dto.ProductRequest; import com.multiaceites.service.ProductService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/productos") @RequiredArgsConstructor public class ProductController{private final ProductService s;@GetMapping public Object all(@RequestParam(required=false) String q){return s.all(q);}@GetMapping("/bajo-stock") public Object low(){return s.lowStock();}@GetMapping("/{id}/historial-precios") public Object history(@PathVariable Long id){return s.priceHistory(id);}@PostMapping public Object save(@Valid @RequestBody ProductRequest r){return s.save(r);}@PutMapping("/{id}") public Object update(@PathVariable Long id,@Valid @RequestBody ProductRequest r){return s.update(id,r);}@DeleteMapping("/{id}") public void delete(@PathVariable Long id){s.delete(id);}}
